=== key selectors ===
#header{background: rgba(0,50,106,0.80);}
#header #zone-utility-bar{padding:10px 0;background-color:#003e78;text-align: right;}
#header #zone-utility-bar .sexual-misconduct{display: inline-block;vertical-align: top;padding-right:15px;}
#header #zone-utility-bar .sexual-misconduct a{position: relative;display: inline-block;padding:8px 32px 8px 10px;background:#ffcb0b;color:#002c5a;text-decoration: none;font-size:12px;line-height:15px;font-family: 'Roboto',sans-serif;border-radius:2px;transition:all 0.2s ease-in-out;}
#header #zone-utility-bar .sexual-misconduct a .fa{position:absolute;right:10px;top:50%;margin-top: -.5em;}
#header #zone-utility-bar .sexual-misconduct a:hover{background:#fddd67;}
#header #zone-utility-bar .search{display: inline-block;vertical-align: top;}
#header #zone-utility-bar .search form{position: relative;text-align: right;}
#header #zone-utility-bar .search form label{display:block;}
#header #zone-utility-bar .search form label input{font-family: 'Roboto',sans-serif;font-size:12px;width:186px;padding:8px 28px 8px 10px;border: none;border-radius:2px;-webkit-appearance: none;}
#header #zone-utility-bar .search form label input[type="search"]::-webkit-search-cancel-button{-webkit-appearance: none;}
#header #zone-utility-bar .search form button{position:absolute;top:50%;right:6px;background: transparent;border: none;margin: -7px 0 0 -17px;padding:0;width:auto;overflow: visible;font-size:14px;cursor: pointer;color:#000;}
#header h1.logo{float: left;margin:0;}
#header h1.logo a{display:block;margin:0;padding:0;background-image: url(/skins/um2013/styles/../media/images/umich-logo.png);background-size:100%;background-color:#00274c;width:132px;height:138px;text-indent: -9000px;}
#header #zone-audience-quick-links{padding-top:30px;font-family: 'Roboto Condensed',sans-serif;font-weight:bold;letter-spacing:1px;}
#header #zone-audience-quick-links #audience-nav{float: left;font-size:11px;margin:0 0 0 30px;text-transform: uppercase;width:690px;}
#header #zone-audience-quick-links #audience-nav ul{margin:0;padding:0;list-style: none;}
#header #zone-audience-quick-links #audience-nav li{float: left;border-top:1px solid #567daa;border-right:1px solid #567daa;border-bottom:1px solid #567daa;background-color:#002c5a;}
#header #zone-audience-quick-links #audience-nav li:first-child{border-left:1px solid #567daa;}
#header #zone-audience-quick-links #audience-nav li:first-child,#header #zone-audience-quick-links #audience-nav li a{display:block;padding:10px 12px;padding:10px;color:#ffcb0b;text-decoration: none;transition:all 0.2s ease-in-out;}
#header #zone-audience-quick-links #audience-nav li a:hover{background-color:#0d57aa;}
#header #zone-audience-quick-links #audience-nav li.active a{background-color:#0d57aa;}
#header #zone-audience-quick-links #quick-links{font-size:12px;float: right;position: relative;z-index:1;}
#header #zone-audience-quick-links #quick-links summary{position: relative;display:block;width:166px;padding:10px;color:#002c5a;background-color:#ffcb0b;text-transform: uppercase;text-decoration: none;line-height:1;cursor: pointer;border-radius:2px 3px 3px 2px;transition:all 0.2s ease-in-out;}
#header #zone-audience-quick-links #quick-links summary .fa{position:absolute;right:0;top:0;padding:4px;background:#444;color:#fff;font-size:16px;border-radius:0 2px 2px 0;}
#header #zone-audience-quick-links #quick-links summary .fa:before{display:block;width:20px;height:20px;border-radius:50%;border:2px solid #fff;line-height:20px;text-align:center;text-indent:1px;content: "\f067";}
#header #zone-audience-quick-links #quick-links summary:hover{background-color:#fddd67;transition:all 0.2s ease-in-out;}
#header #zone-audience-quick-links #quick-links summary:hover .fa{background:#666;}
#header #zone-audience-quick-links #quick-links nav{position:absolute;width:100%;max-height:0;overflow: hidden;visibility: hidden;border-bottom-left-radius:2px;border-bottom-right-radius:2px;}
#header #zone-audience-quick-links #quick-links ul{margin:0;padding:0;list-style: none;font-family: 'Roboto',sans-serif;background-color:#444444;}
#header #zone-audience-quick-links #quick-links li a{display:block;padding:15px;color:#ffffff;text-decoration: none;}
#header #zone-audience-quick-links #quick-links li a:hover{color:#ffcb0b;background-color:#5b5b5b;}
#header #zone-audience-quick-links #quick-links summary:focus{outline:1px auto #efefef;outline-offset: -1px;}
#header #zone-audience-quick-links #quick-links[open] summary{border-bottom-left-radius:0;border-bottom-right-radius:0;}
#header #zone-audience-quick-links #quick-links[open] summary .fa{border-bottom-right-radius:0;}
#header #zone-audience-quick-links #quick-links[open] summary .fa:before{content: "\f068";}
#header #zone-audience-quick-links #quick-links[open] nav{height:auto;max-height:9999px;transition: max-height 1.5s ease-in-out;visibility: visible;}
#header #zone-main-nav{clear:both;border-top:1px solid #567daa;border-bottom:1px solid #567daa;}
#header #zone-main-nav #main-nav{width:100%;font-family: Georgia,"Times New Roman",Times,serif;font-size:16px;}
#header #zone-main-nav #main-nav .hamburger-header{display: none;}
Shell cwd was reset to /workspace/recreation

