input.command:
cd /tmp && python3 << 'PYEOF'
import re
c=open('skin.css').read()
for sel in ['#main-nav ul','#main-nav li','#main-nav li a','#main-nav li.active','.panel .header','.panel','#footer','#footer .','.audience','#content','#features']:
    for m in re.finditer(re.escape(sel)+r'[^{]*\{[^}]*\}', c):
        s=m.group(0)
        if len(s)<400: print(s)
    print('---')
