#main-nav ul{display:flex;margin:0;padding:0;list-style: none;border-right:1px solid #567daa;box-sizing:content-box;}
#main-nav ul li{flex-grow:1;border-left:1px solid #567daa;text-align:center;white-space: nowrap;position: relative;}
#main-nav ul li:before{content: ' ';display:block;position:absolute;top:0;left:50%;height:100%;width:0%;background:#003e78;border-radius:50%;transition:all 0.2s ease-in-out;}
#main-nav ul li:first-child{flex-basis:5%;flex-grow:0;}
#main-nav ul li a{display: inline-block;width:100%;padding:10px 0;color:#ffffff;text-decoration: none;transition:all 0.2s ease-in-out;position: relative;}
#main-nav ul li a:hover{color:#ffcb0b;xbackground-color:#003e78;}
#main-nav ul li:hover:before{width:100%;left:0;border-radius:0;}
#main-nav ul li.active a{color:#ffcb0b;background-color:#003e78;}
#main-nav ul{border-right: none;}
#main-nav ul li:first-child{border-left: none;}
#main-nav ul{display: none;}
#main-nav ul li{display: inherit;float: none;width:auto !important;text-align:center;border-left: none;border-top:1px dotted #567daa;}
