.panel .header{padding:20px 0;text-align:center;font-size:30px;letter-spacing:5px;text-transform: uppercase;}
.panel .header h2{padding:0;font-size: inherit;font-weight: normal;padding-bottom:10px;border-bottom:1px solid;}
.panel .primary{float: left;width:80%;padding:0 10px;}
.panel .secondary{float: right;width:20%;padding:0 10px;}
.panel .nav-block > div{min-height:275px;padding:15px;background-color:#222222;border: solid 1px #4b4b4b;border-radius:2px;}
.panel .nav-block h4{margin:0;padding-bottom:15px;color:#72b4ff;font-size:16px;font-weight:bold;text-transform: uppercase;}
.panel .nav-block ul{margin:0;padding:0;list-style: none;}
.panel .nav-block ul > li{position: relative;padding:10px 0;}
.panel .nav-block ul > li + li{border-top:1px dotted #8e8c8c;}
.panel .nav-block details summary{cursor: pointer;}
.panel .nav-block details summary,.panel .nav-block a{position: relative;color:#ffffff;text-decoration: none;letter-spacing: .5px;line-height:1.2em;}
.panel .nav-block details summary,.panel .nav-block ul li a{display:block;padding-right:25px;}
.panel .nav-block details summary .fa,.panel .nav-block a .fa{position:absolute;right:0;top:0;color:#ffcb0b;line-height:1.2;}
.panel .nav-block .italic{font-style: italic;}
.panel .nav-block em{display:block;font-size:12px;padding-top:3px;line-height:1em;}
.panel .nav-block details summary:hover,.panel .nav-block a:hover{color:#ffcb0b;}
.panel .nav-block details summary:hover span,.panel .nav-block a:hover span{border-bottom:dotted 1px #ffcb0b;}
.panel .nav-block .dropdown .dropdown-content li{padding:5px 0;}
.panel .nav-block .dropdown .dropdown-content li + li{border: none;}
.panel .nav-block .dropdown .dropdown-content li.heading{margin:0 -10px;padding-left:10px;padding-right:10px;border-bottom:1px dotted;}
.panel .nav-block .dropdown .dropdown-content li h5{text-transform: uppercase;color:#ffcb0b;}
.panel .nav-block .dropdown .dropdown-content li a{margin:0;}
.panel .nav-block .dropdown details summary .fa:before{content: "\f055";color:#72b4ff;}
.panel .nav-block .dropdown details[open] summary .fa:before{content: "\f056";}
.panel .nav-block .dropdown details .dropdown-content{display:block;position:absolute;width:100%;max-height:0;padding:0;margin-top:11px;background:#4b4b4b;z-index:1;font-size:16px;line-height:26px;visibility: hidden;overflow: hidden;box-sizing:border-box;}
.panel .nav-block .dropdown details[open] .dropdown-content{padding:10px;height:auto;max-height:9999px;transition: max-height 1.5s ease-in-out;visibility: visible;}
.panel .nav-block .dropdown details summary:focus{color:#ffcb0b;}
.panel .nav-block .dropdown details summary:focus span{border-bottom:1px dotted #ffcb0b;}
.panel.grey{background-color:#333333;color:#a1a1a1;}
.panel.light-grey{background-color:#efefef;color:#000000;}
.panel.white{background:#fff;color:#333;}
.panel.white .header{color:#6189b7;}
.panel.maize{background-color:#ffcb0b;color:#333;}
.panel.maize .header{color:#636363;}
.panel.blue{background-color:#00274c;color:#a1a1a1;}
.panel.blue a{color:#ffcb0b;}
.panel .header{padding-left:10px;padding-right:10px;}
.panel .primary{width:70%;}
.panel .secondary{width:30%;}
.panel.audience .content{letter-spacing:1px;padding-bottom:20px;}
.panel.audience .description{padding:0 20px 40px 20px;text-align:center;line-height:22px;}
.panel.audience .primary.has-nav-blocks{margin: -10px;display:flex;flex-wrap: wrap;}
.panel.audience .nav-block{flex-basis:33.3333%;padding:10px;}
.panel.audience .secondary .feature img{border-radius:2px;}
.panel.audience .secondary .feature .caption{font-family: Georgia,"Times New Roman",Times,serif;font-size:13px;color:#ffcb0b;padding:8px 0;line-height:16px;max-width:240px;}
.panel.audience .secondary .feature .caption span{display:block;padding-top:10px;}
.panel.audience .secondary .feature .caption a{color:#ffcb0b;text-decoration: none;border-bottom:1px solid transparent;}
.panel.audience .secondary .feature .caption a .fa{padding-left:10px;}
.panel.audience .secondary .feature .caption a:hover{border-bottom:1px dotted;}
.panel.audience .secondary .feature + .infographics{margin-top:80px;}
.panel.audience .nav-block{flex-basis:50%;}
.panel.audience .primary{width:100%;float: none;}
.panel.audience .primary.has-nav-blocks{margin: -10px 0 0 0;padding:0;}
.panel.audience .secondary{display: none;}
.panel.audience .nav-block{flex-basis:100%;}
.panel.content .content{padding:40px 0;font-family: 'Roboto',sans-serif;font-size:18px;max-width:960px;}
.panel.light-grey.content .header{background-color:#333333;color:#a1a1a1;}
.panel.light-grey.content .header h2{padding-bottom:0;border-bottom: none;}
.panel.content .description{padding:0 20px 40px 20px;text-align:center;line-height:22px;}
.panel.content .content h3{color:#000;font-size:30px;font-family: 'Roboto',sans-serif;font-weight: normal;margin:10px 0;}
.panel.content .content h4{color:#4F4F4F;font-size:26px;font-family: 'Roboto',sans-serif;font-weight:bold;text-transform: initial;margin:10px 0;}
.panel.content .content h5{color:#333;font-size:20px;font-family: 'Roboto',sans-serif;font-weight:bold;text-transform: initial;margin:10px 0;}
.panel.content .content h6{color:#7a121c;font-size:18px;font-family: 'Roboto',sans-serif;font-weight:bold;text-transform: initial;margin:10px 0;}
.panel.content .content * ~ h3,.panel.content .content * ~ h4,.panel.content .content * ~ h5,.panel.content .content * ~ h6{margin-top:20px;}
.panel.content .content a{color:#0d57aa;border-bottom:1px dotted;text-decoration: none;}
.panel.content .content a:hover{color:#72b4ff;border-bottom-color: transparent;}
.panel.content .content strong{font-weight:bold;}
.panel.content .content p{margin:15px 0;line-height:1.3;line-height:1.75;}
.panel.content .content blockquote{font-size:20px;margin:20px 0;padding:20px 10%;border-top:1px solid #555;border-bottom:1px solid #555;text-align:center;line-height:1.5;}
.panel.content .content ul,.panel.content .content ol{xpadding:15px 0;padding:0;margin:15px 0 15px 30px;}
.panel.content .content ul ul,.panel.content .content ul ol,.panel.content .content ol ul,.panel.content .content ol ol{margin-top:10px;}
.panel.content .content ul ul{list-style:circle;}
.panel.content .content ol ol{list-style: lower-roman;}
.panel.content .content ul li,.panel.content .content ol li{line-height:1.4;}
.panel.content .content ul li + li,.panel.content .content ol li + li{margin-top:5px;}
.panel.content .content ul{list-style-type:disc;}
.panel.content .content ol{list-style-type:decimal;}
.panel.content.grey .content h3{color:#eee;}
.panel.content.grey .content h4{color:#ffcb0b;color:#72b4ff;}
.panel.content.grey .content h5{color:#a1a1a1;}
.panel.content.grey .content h6{color:#ff4500;}
.panel.content.grey .content a{color:#ffcb0b;}
.panel.content.blue .content h3{color:#eee;}
.panel.content.blue .content h4{color:#ffcb0b;}
.panel.content.blue .content h5{color:#a1a1a1;font-weight:bold;}
.panel.content.blue .content h6{color:#ff4500;}
.panel.content.blue .content a{color:#ffcb0b;}
.panel.content .content{padding-left:10px;padding-right:10px;}
.panel.audience
   nav-blocks, so it is unaffected. */
