content.content:
.fa-hamburger{--fa: "\f805";}
#header #zone-main-nav{clear:both;border-top:1px solid #567daa;border-bottom:1px solid #567daa;}
#header #zone-main-nav #main-nav{width:100%;font-family: Georgia,"Times New Roman",Times,serif;font-size:16px;}
#header #zone-main-nav #main-nav .hamburger-header{display: none;}
#header #zone-main-nav #main-nav ul{display:flex;margin:0;padding:0;list-style: none;border-right:1px solid #567daa;box-sizing:content-box;}
#header #zone-main-nav #main-nav ul li{flex-grow:1;border-left:1px solid #567daa;text-align:center;white-space: nowrap;position: relative;}
#header #zone-main-nav #main-nav ul li:before{content: ' ';display:block;position:absolute;top:0;left:50%;height:100%;width:0%;background:#003e78;border-radius:50%;transition:all 0.2s ease-in-out;}
#header #zone-main-nav #main-nav ul li:first-child{flex-basis:5%;flex-grow:0;}
#header #zone-main-nav #main-nav ul li a{display: inline-block;width:100%;padding:10px 0;color:#ffffff;text-decoration: none;transition:all 0.2s ease-in-out;position: relative;}
#header #zone-main-nav #main-nav ul li a:hover{color:#ffcb0b;xbackground-color:#003e78;}
#header #zone-main-nav #main-nav ul li:hover:before{width:100%;left:0;border-radius:0;}
#header #zone-main-nav #main-nav ul li.active a{color:#ffcb0b;background-color:#003e78;}
#header #zone-main-nav #main-nav{font-size:13px;}
#header #zone-main-nav #main-nav ul{border-right: none;}
#header #zone-main-nav #main-nav ul li:first-child{border-left: none;}
#header #zone-main-nav #main-nav{font-size:15px;background-color:#003e78;}
#header #zone-main-nav #main-nav .hamburger-header{display:block;cursor: pointer;}
#header #zone-main-nav #main-nav .hamburger-header:hover{background-color:#003e78;}
#header #zone-main-nav #main-nav .hamburger-header h3{padding:12px;color:#ffcb0b;font-family: 'Roboto Condensed',sans-serif;font-size:20px;font-weight:bold;text-transform: uppercase;}
#header #zone-main-nav #main-nav .hamburger-header h3 .fa{margin-right:5px;}
#header #zone-main-nav #main-nav ul{display: none;}
#header #zone-main-nav #main-nav ul li{display: inherit;float: none;width:auto !important;text-align:center;border-left: none;border-top:1px dotted #567daa;}
